// =============================================================================
// SIGNATURE CÉLESTE — interprétation individualisée des grandes figures (LLM).
// -----------------------------------------------------------------------------
// Principe (verrouillé 2026-06-18, Option B) :
//   1. Fiche factuelle 100 % DÉTERMINISTE par figure (membres + signe + maison
//      + domaine + composition d'aspects) — calculée ici, jamais par le LLM.
//   2. LLM Gemini 3.1 Pro en « monde fermé » : il n'interprète QUE ces faits,
//      n'ajoute aucun astre / maison / signe / aspect absent de la fiche.
//   3. Sortie bilingue gérée par appel unique dans la langue + l'adresse du
//      rapport (tu / vous / il / elle  —  you / he / she).
//   4. Validation post-LLM : adresse cohérente + aucun astre hors fiche,
//      sinon FALLBACK automatique sur le texte statique du générateur.
//
// Le modèle est IDENTIQUE à la chaîne THEME existante : models/gemini-3.1-pro-preview.
// Ce module est conçu pour être réutilisé tel quel comme nœud Code n8n (THEME).
// =============================================================================

const GEMINI_MODEL = 'models/gemini-3.1-pro-preview';
const GEMINI_ENDPOINT = (model, key) =>
  `https://generativelanguage.googleapis.com/v1beta/${model}:generateContent?key=${key}`;

// --- Lexiques (miroir du générateur _theme-spikka-poc.js — source de vérité) ---
const ANGLE_HOUSE = { 'Ascendant': 1, 'AC': 1, 'Imum Coeli': 4, 'Fond du Ciel': 4, 'IC': 4, 'Descendant': 7, 'DC': 7, 'Milieu du Ciel': 10, 'MC': 10 };
const ANGLE_SET = new Set(Object.keys(ANGLE_HOUSE));
const ANGLE_FR2EN = { 'Ascendant': 'Ascendant', 'Milieu du Ciel': 'Midheaven', 'Descendant': 'Descendant', 'Imum Coeli': 'Imum Coeli', 'Fond du Ciel': 'Imum Coeli' };

const PLANET_KW = {
  'Soleil': { fr: 'identité & vitalité', en: 'identity & vitality', en_name: 'Sun' },
  'Lune': { fr: 'émotions & besoins intimes', en: 'emotions & inner needs', en_name: 'Moon' },
  'Mercure': { fr: 'intellect & communication', en: 'intellect & communication', en_name: 'Mercury' },
  'Vénus': { fr: 'désirs, valeurs & amours', en: 'desires, values & loves', en_name: 'Venus' },
  'Mars': { fr: 'action & combativité', en: 'action & drive', en_name: 'Mars' },
  'Jupiter': { fr: 'expansion & chance', en: 'expansion & luck', en_name: 'Jupiter' },
  'Saturne': { fr: 'structure & discipline', en: 'structure & discipline', en_name: 'Saturn' },
  'Uranus': { fr: "besoin d'émancipation", en: 'need for freedom', en_name: 'Uranus' },
  'Neptune': { fr: 'intuition & idéalisme', en: 'intuition & idealism', en_name: 'Neptune' },
  'Pluton': { fr: 'métamorphoses & instincts', en: 'transformations & instincts', en_name: 'Pluto' },
  'Chiron': { fr: 'blessure & guérison', en: 'wound & healing', en_name: 'Chiron' },
  'Nœud Nord': { fr: "mission d'évolution", en: 'evolutionary mission', en_name: 'North Node' },
  'Nœud Sud': { fr: 'zone de confort innée', en: 'innate comfort zone', en_name: 'South Node' },
  'Lilith': { fr: "part d'ombre & rébellion", en: 'shadow & rebellion', en_name: 'Lilith' },
  'Cérès': { fr: 'soin', en: 'care', en_name: 'Ceres' },
  'Pallas': { fr: 'stratégie', en: 'strategy', en_name: 'Pallas' },
  'Junon': { fr: 'engagement', en: 'commitment', en_name: 'Juno' },
  'Vesta': { fr: 'dévotion', en: 'devotion', en_name: 'Vesta' },
  'Vertex': { fr: 'rencontres clés', en: 'key encounters', en_name: 'Vertex' },
};
const ANGLE_KW = {
  'Ascendant': { fr: 'masque social & élan vital', en: 'social mask & vital drive', ab: 'AC' },
  'Milieu du Ciel': { fr: 'sommet & accomplissement', en: 'summit & achievement', ab: 'MC' },
  'Descendant': { fr: "rapport à l'Autre", en: 'relationship to the Other', ab: 'DC' },
  'Imum Coeli': { fr: 'racines & sanctuaire', en: 'roots & sanctuary', ab: 'IC' },
  'Fond du Ciel': { fr: 'racines & sanctuaire', en: 'roots & sanctuary', ab: 'IC' },
};
const HOUSE_KW = {
  1: { fr: 'Identité, image & tempérament', en: 'Identity, image & temperament' },
  2: { fr: 'Ressources matérielles & valeurs', en: 'Material resources & values' },
  3: { fr: 'Communication & entourage proche', en: 'Communication & close circle' },
  4: { fr: 'Racines, foyer & fondations', en: 'Roots, home & foundations' },
  5: { fr: 'Créativité, plaisirs & rayonnement', en: 'Creativity, pleasures & self-expression' },
  6: { fr: 'Quotidien, routines & équilibre', en: 'Daily life, routines & balance' },
  7: { fr: 'Partenariats, couple & associations', en: 'Partnerships, couple & alliances' },
  8: { fr: 'Transformations, crises & intimité', en: 'Transformations, crises & intimacy' },
  9: { fr: 'Quête de sens, horizons & idéaux', en: 'Quest for meaning, horizons & ideals' },
  10: { fr: 'Vocation, sommet social & carrière', en: 'Vocation, social summit & career' },
  11: { fr: 'Projets collectifs, réseaux & amitiés', en: 'Collective projects, networks & friendships' },
  12: { fr: 'Inconscient, spiritualité & lâcher-prise', en: 'Unconscious, spirituality & letting go' },
};
// Composition d'aspects canonique (miroir SIG_ASPECTS du générateur).
const ASPECT_NAMES = {
  conj: { fr: 'Conjonction', en: 'Conjunction', plFr: 'Conjonctions', plEn: 'Conjunctions' },
  opp: { fr: 'Opposition', en: 'Opposition', plFr: 'Oppositions', plEn: 'Oppositions' },
  carre: { fr: 'Carré', en: 'Square', plFr: 'Carrés', plEn: 'Squares' },
  trig: { fr: 'Trigone', en: 'Trine', plFr: 'Trigones', plEn: 'Trines' },
  sext: { fr: 'Sextile', en: 'Sextile', plFr: 'Sextiles', plEn: 'Sextiles' },
};
const SIG_ASPECTS = {
  stellium: [['conj', null]], amas: [['conj', null]],
  croixFixe: [['opp', 2], ['carre', 4]], croixCardinale: [['opp', 2], ['carre', 4]],
  croixMutable: [['opp', 2], ['carre', 4]], grandCarre: [['opp', 2], ['carre', 4]],
  tcarre: [['opp', 1], ['carre', 2]], grandTrigone: [['trig', 3]],
  rectangle: [['opp', 2], ['trig', 2], ['sext', 2]], cerfvolant: [['trig', 3], ['opp', 1], ['sext', 2]],
  yod: [], default: [],
};

function sigKey(type) {
  const t = String(type || '');
  if (/Stellium/i.test(t)) return 'stellium';
  if (/Amas|Cluster/i.test(t)) return 'amas';
  if (/Croix\s*Fixe|Fixed\s*Cross/i.test(t)) return 'croixFixe';
  if (/Croix\s*Cardinal|Cardinal\s*Cross/i.test(t)) return 'croixCardinale';
  if (/Croix\s*Mutable|Mutable\s*Cross/i.test(t)) return 'croixMutable';
  if (/Grand\s*Carré|Grand\s*Cross/i.test(t)) return 'grandCarre';
  if (/T-?\s*Carré|Tau\s*Carré|Carré\s*en\s*T|T-?\s*Square/i.test(t)) return 'tcarre';
  if (/Grand\s*Trigone|Grand\s*Trine/i.test(t)) return 'grandTrigone';
  if (/Rectangle/i.test(t)) return 'rectangle';
  if (/Cerf|Kite/i.test(t)) return 'cerfvolant';
  if (/Yod/i.test(t)) return 'yod';
  return 'default';
}

function aspectsLabel(key, isEN) {
  return (SIG_ASPECTS[key] || []).map(([code, count]) => {
    const a = ASPECT_NAMES[code];
    if (count == null) return isEN ? a.plEn : a.plFr;
    return `${count} ${count > 1 ? (isEN ? a.plEn : a.plFr) : (isEN ? a.en : a.fr)}`;
  }).join(' + ');
}

// Mode d'adresse — IDENTIQUE à getMode() du générateur (tu/vous/il/elle - you/he/she).
function figureMode(consigne, genre, lang) {
  const c = String(consigne || '').trim().toLowerCase();
  const f = String(genre || '').trim().toUpperCase().startsWith('F');
  if (lang === 'en') { if (c.startsWith('il') || c.startsWith('elle') || c.includes('3') || c.includes('he') || c.includes('she')) return f ? 'she' : 'he'; return 'you'; }
  if (c.startsWith('vous')) return 'vous';
  if (c.startsWith('tu')) return 'tu';
  if (c.startsWith('il') || c.startsWith('elle') || c.includes('3')) return f ? 'elle' : 'il';
  return 'tu';
}

function buildFigureMaps(astroData) {
  const houseOf = {}, signOf = {};
  for (const m of (astroData.maisons || [])) {
    // Les locataires peuvent être au niveau maison OU nichés dans les segments
    // (cuspide / interception / fin de maison) selon la version de l'enrichissement.
    const locs = [...(m.locataires || [])];
    for (const seg of (m.segments || [])) for (const l of (seg.locataires || [])) locs.push(l);
    for (const loc of locs) {
      const nm = loc.planetName || loc.planete;
      if (nm && houseOf[nm] == null) houseOf[nm] = m.maison;
    }
  }
  for (const p of (astroData.planetes || [])) {
    const nm = p && p.planet && p.planet.fr;
    if (nm) signOf[nm] = p.zodiac_sign && p.zodiac_sign.name && p.zodiac_sign.name.fr;
  }
  return { houseOf, signOf };
}

// Sélection IDENTIQUE au générateur : top 3 figures de types DISTINCTS, triées
// par puissanceScore décroissant (sinon textes statiques en doublon).
function selectTopFigures(configurations) {
  const seen = new Set();
  const top = [];
  for (const c of [...(configurations || [])].sort((a, b) => (b.puissanceScore || 0) - (a.puissanceScore || 0))) {
    const k = sigKey(c.type);
    if (seen.has(k)) continue;
    seen.add(k);
    top.push(c);
    if (top.length >= 3) break;
  }
  return top;
}

function figureFacts(c, astroData, maps) {
  const m = maps || buildFigureMaps(astroData);
  const key = sigKey(c.type);
  const members = (c.planets || []).map(name => {
    const estAngle = ANGLE_SET.has(name);
    const maison = estAngle ? ANGLE_HOUSE[name] : (m.houseOf[name] ?? null);
    const signe = m.signOf[name] || null;
    const kw = estAngle ? (ANGLE_KW[name] || null) : (PLANET_KW[name] || null);
    return { astre: name, estAngle, maison, signe, motcle: kw };
  });
  const houseNums = [...new Set(members.map(x => x.maison).filter(Boolean))].sort((a, b) => a - b);
  const housesCovered = houseNums.map(n => ({ n, domaine: HOUSE_KW[n] || null }));
  return { type: c.type, key, members, housesCovered, aspectsFr: aspectsLabel(key, false), aspectsEn: aspectsLabel(key, true) };
}

// --- Fiche factuelle rendue en texte (lue par le LLM) ------------------------
function factsToText(facts, isEN, idx) {
  const L = (o) => o ? (isEN ? o.en : o.fr) : '';
  const membersTxt = facts.members.map(m => {
    const dom = m.estAngle ? (m.motcle ? L(m.motcle) : '') : (m.motcle ? L(m.motcle) : '');
    const name = isEN && !m.estAngle ? (PLANET_KW[m.astre]?.en_name || m.astre)
      : isEN && m.estAngle ? (ANGLE_FR2EN[m.astre] || m.astre) : m.astre;
    const parts = [`- ${name}`];
    if (dom) parts.push(`(${isEN ? 'role' : 'rôle'}: ${dom})`);
    if (m.signe) parts.push(isEN ? `in ${m.signe}` : `en ${m.signe}`);
    if (m.maison) parts.push(isEN ? `— House ${m.maison}: ${L(HOUSE_KW[m.maison])}` : `— Maison ${m.maison} : ${L(HOUSE_KW[m.maison])}`);
    return parts.join(' ');
  }).join('\n');
  const houses = facts.housesCovered.map(h => `${isEN ? 'House' : 'Maison'} ${h.n} (${L(h.domaine)})`).join(isEN ? ' and ' : ' et ');
  const aspects = isEN ? facts.aspectsEn : facts.aspectsFr;
  return [
    `### ${isEN ? 'FIGURE' : 'FIGURE'} ${idx + 1} — id="${idx}" — ${facts.type}`,
    `${isEN ? 'Members' : 'Membres'} :`,
    membersTxt,
    aspects ? `${isEN ? 'Geometric composition' : 'Composition géométrique'} : ${aspects}` : '',
    houses ? `${isEN ? 'Life areas activated' : 'Domaines de vie activés'} : ${houses}` : '',
  ].filter(Boolean).join('\n');
}

// --- Consignes d'adresse (tu/vous/il/elle — you/he/she) ----------------------
function addressInstruction(mode, prenom, isEN) {
  const p = prenom || (isEN ? 'the person' : 'la personne');
  if (isEN) {
    if (mode === 'he') return `Write in the THIRD PERSON MASCULINE about ${p} (use "he/his"). Never use "you/your".`;
    if (mode === 'she') return `Write in the THIRD PERSON FEMININE about ${p} (use "she/her"). Never use "you/your".`;
    return `Write addressing the reader directly in the SECOND PERSON (use "you/your"). Never use "he/she/his/her".`;
  }
  if (mode === 'tu') return `Rédige en TUTOIEMENT direct (utilise "tu", "ton/ta/tes"). N'utilise JAMAIS "vous", "votre/vos", ni la 3e personne (il/elle, son/sa/ses).`;
  if (mode === 'il') return `Rédige à la TROISIÈME PERSONNE MASCULINE à propos de ${p} (utilise "il", "son/sa/ses"). N'utilise JAMAIS "tu" ni "vous".`;
  if (mode === 'elle') return `Rédige à la TROISIÈME PERSONNE FÉMININE à propos de ${p} (utilise "elle", "son/sa/ses"). N'utilise JAMAIS "tu" ni "vous".`;
  return `Rédige en VOUVOIEMENT direct (utilise "vous", "votre/vos"). N'utilise JAMAIS "tu", "ton/ta/tes", ni la 3e personne (il/elle, son/sa/ses).`;
}

function buildPrompt(topFacts, opts) {
  const isEN = opts.lang === 'en';
  const addr = addressInstruction(opts.mode, opts.prenom, isEN);
  const figuresBlock = topFacts.map((f, i) => factsToText(f, isEN, i)).join('\n\n');
  const system = isEN
    ? `You are a master astrologer AND a psychology populariser writing for a paying client who knows nothing about astrology. You interpret the major geometric figures of a birth chart in a warm, embodied, non-technical voice.\n\nABSOLUTE RULES (closed world):\n- Interpret ONLY the facts given for each figure. NEVER mention a planet, angle, sign, house or aspect that is not explicitly listed in that figure's fact sheet.\n- NEVER invent degrees, dates, transits or extra figures.\n- Keep nuance: if a figure is a challenge, name the difficulty honestly FIRST, then turn it into a strength (à la "Algol" reframing). If it is a gift, celebrate it but flag the one pitfall.\n- No jargon words: never write "conjunction, opposition, square, trine, sextile, cusp, orb, stellium, aspect". Translate them into lived experience.\n- ${addr}`
    : `Tu es un maître astrologue ET un vulgarisateur en psychologie qui écrit pour un client payant n'y connaissant rien en astrologie. Tu interprètes les grandes figures géométriques d'un thème natal d'une voix chaleureuse, incarnée et sans jargon.\n\nRÈGLES ABSOLUES (monde fermé) :\n- Interprète UNIQUEMENT les faits donnés pour chaque figure. Ne mentionne JAMAIS une planète, un angle, un signe, une maison ou un aspect qui n'est pas explicitement listé dans la fiche de CETTE figure.\n- N'invente JAMAIS de degrés, dates, transits ou figures supplémentaires.\n- Garde la nuance : si une figure est un défi, nomme honnêtement la difficulté D'ABORD, puis transforme-la en force (esprit du recadrage "Algol"). Si c'est un don, célèbre-le mais signale l'unique piège.\n- Zéro jargon : n'écris JAMAIS "conjonction, opposition, carré, trigone, sextile, cuspide, orbe, stellium, aspect". Traduis-les en expérience vécue.\n- ${addr}`;

  const user = isEN
    ? `Here are the major figures of the chart, with their VERIFIED facts:\n\n${figuresBlock}\n\nFor EACH figure, write:\n- "synth": EXACTLY 2 short sentences (≈36 words TOTAL, hard cap 42), describing what this specific figure means for this person, weaving in the ACTUAL planets, signs and life areas listed (e.g. a figure straddling House 9 and House 10 must be described as bridging meaning-seeking and career). Be vivid but very tight: no filler, no redundant adjectives, no warm-up clause.\n- "action": 1 short concrete "in practice" sentence of advice (≈14 words max).\n\nReturn STRICT JSON only, no prose, exactly this shape:\n{"0":{"synth":"...","action":"..."},"1":{...},...} using the id of each figure as the key.`
    : `Voici les grandes figures du thème, avec leurs faits VÉRIFIÉS :\n\n${figuresBlock}\n\nPour CHAQUE figure, rédige :\n- "synth" : EXACTEMENT 2 phrases courtes (≈36 mots AU TOTAL, plafond strict 42), décrivant ce que cette figure précise signifie pour cette personne, en tissant les planètes, signes et domaines de vie RÉELLEMENT listés (ex. une figure à cheval entre Maison 9 et Maison 10 doit être décrite comme un pont entre quête de sens et carrière). Sois vivant mais très resserré : aucun remplissage, pas d'adjectifs redondants, pas de clause d'introduction.\n- "action" : 1 phrase courte et concrète de conseil "en pratique" (≈14 mots max).\n\nRéponds UNIQUEMENT en JSON STRICT, sans prose, exactement cette forme :\n{"0":{"synth":"...","action":"..."},"1":{...},...} en utilisant l'id de chaque figure comme clé.`;
  return { system, user };
}

// --- Validation post-LLM (adresse + monde fermé) -----------------------------
const ALL_ASTRE_NAMES = (() => {
  const s = new Set();
  for (const fr of Object.keys(PLANET_KW)) { s.add(fr); if (PLANET_KW[fr].en_name) s.add(PLANET_KW[fr].en_name); }
  for (const fr of Object.keys(ANGLE_KW)) { s.add(fr); s.add(ANGLE_KW[fr].ab); }
  for (const fr of Object.keys(ANGLE_FR2EN)) s.add(ANGLE_FR2EN[fr]);
  return [...s];
})();
const FORBIDDEN_BY_MODE = {
  tu: [/\b(vous|votre|vos)\b/i],
  vous: [/\b(tu|ton|ta|tes)\b/i],
  il: [/\b(tu|ton|ta|tes|vous|votre|vos)\b/i],
  elle: [/\b(tu|ton|ta|tes|vous|votre|vos)\b/i],
  you: [/\b(his|her|hers)\b/i],
  he: [/\b(your|yours)\b/i],
  she: [/\b(your|yours)\b/i],
};

// Frontières conscientes des accents : en JS, \b traite « é » comme non-mot, ce
// qui fait matcher l'abréviation « AC » dans « acérée ». On encadre donc chaque
// terme par des lookarounds excluant toute lettre (accents compris) ou chiffre.
const _LET = 'A-Za-zÀ-ÖØ-öø-ÿ0-9_';
function _astreRe(name) {
  const esc = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // Abréviation courte (AC, MC, DC, IC, FC) : casse stricte (un vrai jargon
  // serait en majuscules ; « ac/ic » minuscules dans un mot FR sont ignorés).
  const isAbbr = /^[A-Z]{1,3}$/.test(name);
  return new RegExp(`(?<![${_LET}])${esc}(?![${_LET}])`, isAbbr ? '' : 'i');
}
function validateText(text, mode, allowedAstres) {
  const t = String(text || '');
  if (!t.trim()) return { ok: false, reason: 'empty' };
  for (const re of (FORBIDDEN_BY_MODE[mode] || [])) {
    if (re.test(t)) return { ok: false, reason: `address mismatch (${mode}): ${re}` };
  }
  // Monde fermé : aucun nom d'astre connu hors de la fiche de la figure.
  const allowed = new Set(allowedAstres);
  for (const name of ALL_ASTRE_NAMES) {
    if (allowed.has(name)) continue;
    if (_astreRe(name).test(t)) return { ok: false, reason: `foreign body mentioned: ${name}` };
  }
  return { ok: true };
}

function allowedAstresFor(facts) {
  const out = [];
  for (const m of facts.members) {
    out.push(m.astre);
    if (PLANET_KW[m.astre]?.en_name) out.push(PLANET_KW[m.astre].en_name);
    if (ANGLE_KW[m.astre]) { out.push(ANGLE_KW[m.astre].ab); out.push(ANGLE_FR2EN[m.astre] || m.astre); }
  }
  return out;
}

async function callGemini(prompt, apiKey, opts = {}) {
  const body = {
    systemInstruction: { parts: [{ text: prompt.system }] },
    contents: [{ role: 'user', parts: [{ text: prompt.user }] }],
    generationConfig: { temperature: opts.temperature ?? 0.45, responseMimeType: 'application/json', maxOutputTokens: opts.maxOutputTokens ?? 2048 },
  };
  const res = await fetch(GEMINI_ENDPOINT(GEMINI_MODEL, apiKey), {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`Gemini HTTP ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const data = await res.json();
  const text = data?.candidates?.[0]?.content?.parts?.map(p => p.text).join('') || '';
  if (!text.trim()) throw new Error('Gemini: réponse vide');
  return JSON.parse(text);
}

// =============================================================================
// API principale : enrichit astroData.configurations IN PLACE avec llmSynth /
// llmAction (validés). Idempotent et sûr : si pas de clé ou échec → no-op
// (le générateur retombe sur les textes statiques).
// =============================================================================
async function enrichFiguresWithLLM(astroData, opts = {}) {
  const stats = { attempted: 0, applied: 0, fallback: 0, reasons: [] };
  const apiKey = opts.apiKey || process.env.GEMINI_API_KEY || process.env.GOOGLE_GENERATIVE_AI_API_KEY || process.env.GOOGLE_API_KEY;
  const configs = astroData?.configurations || [];
  if (!configs.length) return stats;
  if (!apiKey) { stats.reasons.push('no GEMINI_API_KEY → static fallback'); return stats; }

  const maps = buildFigureMaps(astroData);
  const top = selectTopFigures(configs);
  const topFacts = top.map(c => figureFacts(c, astroData, maps));
  stats.attempted = top.length;

  let parsed;
  try {
    const prompt = buildPrompt(topFacts, opts);
    parsed = await callGemini(prompt, apiKey, opts);
  } catch (e) {
    stats.reasons.push('LLM call failed: ' + e.message);
    stats.fallback = top.length;
    return stats;
  }

  top.forEach((c, i) => {
    const r = parsed?.[String(i)] || parsed?.[i];
    if (!r || typeof r !== 'object') { stats.fallback++; stats.reasons.push(`fig ${i}: missing in JSON`); return; }
    const allowed = allowedAstresFor(topFacts[i]);
    const vs = validateText(r.synth, opts.mode, allowed);
    const va = validateText(r.action, opts.mode, allowed);
    if (!vs.ok || !va.ok) { stats.fallback++; stats.reasons.push(`fig ${i}: ${vs.ok ? va.reason : vs.reason}`); return; }
    c.llmSynth = String(r.synth).trim();
    c.llmAction = String(r.action).trim();
    stats.applied++;
  });
  return stats;
}

const _internals = { figureFacts, buildPrompt, buildFigureMaps, selectTopFigures, validateText, factsToText, allowedAstresFor };


// ===== Driver harness : « Figures · Fiche & Prompt » (test isolé, 0 LLM) ======
// Variante du Prep pour le mini-workflow de TEST. Lit vars/astro depuis le corps
// du webhook ({ vars, astro, who }) au lieu des nœuds amont de la chaîne THEME.
const _in = (() => { try { return $input.first().json || {}; } catch (e) { return {}; } })();
const _root = _in.body || _in;
const _vars = _root.vars || {};
const _astro = _root.astro || {};
const _who = _root.who || '';
const _lang = (_vars.langue && _vars.langue !== 'Français') ? 'en' : 'fr';
