function sigKey(type) {
  const t = String(type || '');
  if (/Stellium/i.test(t)) return 'stellium';
  if (/Amas|Cluster/i.test(t)) return 'amas';
  if (/Croix\s*Fixe|Fixed\s*Cross/i.test(t)) return 'croixFixe';
  if (/Croix\s*Cardinal|Cardinal\s*Cross/i.test(t)) return 'croixCardinale';
  if (/Croix\s*Mutable|Mutable\s*Cross/i.test(t)) return 'croixMutable';
  if (/Grand\s*Carré|Grand\s*Cross/i.test(t)) return 'grandCarre';
  if (/T-?\s*Carré|Tau\s*Carré|Carré\s*en\s*T|T-?\s*Square/i.test(t)) return 'tcarre';
  if (/Grand\s*Trigone|Grand\s*Trine/i.test(t)) return 'grandTrigone';
  if (/Rectangle/i.test(t)) return 'rectangle';
  if (/Cerf|Kite/i.test(t)) return 'cerfvolant';
  if (/Yod/i.test(t)) return 'yod';
  return 'default';
}

function aspectsLabel(key, isEN) {
  return (SIG_ASPECTS[key] || []).map(([code, count]) => {
    const a = ASPECT_NAMES[code];
    if (count == null) return isEN ? a.plEn : a.plFr;
    return `${count} ${count > 1 ? (isEN ? a.plEn : a.plFr) : (isEN ? a.en : a.fr)}`;
  }).join(' + ');
}

// Mode d'adresse — IDENTIQUE à getMode() du générateur (tu/vous/il/elle - you/he/she).
function figureMode(consigne, genre, lang) {
  const c = String(consigne || '').trim().toLowerCase();
  const f = String(genre || '').trim().toUpperCase().startsWith('F');
  if (lang === 'en') { if (c.startsWith('il') || c.startsWith('elle') || c.includes('3') || c.includes('he') || c.includes('she')) return f ? 'she' : 'he'; return 'you'; }
  if (c.startsWith('vous')) return 'vous';
  if (c.startsWith('tu')) return 'tu';
  if (c.startsWith('il') || c.startsWith('elle') || c.includes('3')) return f ? 'elle' : 'il';
  return 'tu';
}

function buildFigureMaps(astroData) {
  const houseOf = {}, signOf = {};
  for (const m of (astroData.maisons || [])) {
    // Les locataires peuvent être au niveau maison OU nichés dans les segments
    // (cuspide / interception / fin de maison) selon la version de l'enrichissement.
    const locs = [...(m.locataires || [])];
    for (const seg of (m.segments || [])) for (const l of (seg.locataires || [])) locs.push(l);
    for (const loc of locs) {
      const nm = loc.planetName || loc.planete;
      if (nm && houseOf[nm] == null) houseOf[nm] = m.maison;
    }
  }
  for (const p of (astroData.planetes || [])) {
    const nm = p && p.planet && p.planet.fr;
    if (nm) signOf[nm] = p.zodiac_sign && p.zodiac_sign.name && p.zodiac_sign.name.fr;
  }
  return { houseOf, signOf };
}

// Sélection IDENTIQUE au générateur : top 3 figures de types DISTINCTS, triées
// par puissanceScore décroissant (sinon textes statiques en doublon).
function selectTopFigures(configurations) {
  const seen = new Set();
  const top = [];
  for (const c of [...(configurations || [])].sort((a, b) => (b.puissanceScore || 0) - (a.puissanceScore || 0))) {
    const k = sigKey(c.type);
    if (seen.has(k)) continue;
    seen.add(k);
    top.push(c);
    if (top.length >= 3) break;
  }
  return top;
}

function figureFacts(c, astroData, maps) {
  const m = maps || buildFigureMaps(astroData);
  const key = sigKey(c.type);
  const members = (c.planets || []).map(name => {
    const estAngle = ANGLE_SET.has(name);
    const maison = estAngle ? ANGLE_HOUSE[name] : (m.houseOf[name] ?? null);
    const signe = m.signOf[name] || null;
    const kw = estAngle ? (ANGLE_KW[name] || null) : (PLANET_KW[name] || null);
    return { astre: name, estAngle, maison, signe, motcle: kw };
  });
  const houseNums = [...new Set(members.map(x => x.maison).filter(Boolean))].sort((a, b) => a - b);
  const housesCovered = houseNums.map(n => ({ n, domaine: HOUSE_KW[n] || null }));
  return { type: c.type, key, members, housesCovered, aspectsFr: aspectsLabel(key, false), aspectsEn: aspectsLabel(key, true) };
}

// --- Fiche factuelle rendue en texte (lue par le LLM) ------------------------
function factsToText(facts, isEN, idx) {
  const L = (o) => o ? (isEN ? o.en : o.fr) : '';
  const membersTxt = facts.members.map(m => {
    const dom = m.estAngle ? (m.motcle ? L(m.motcle) : '') : (m.motcle ? L(m.motcle) : '');
    const name = isEN && !m.estAngle ? (PLANET_KW[m.astre]?.en_name || m.astre)
      : isEN && m.estAngle ? (ANGLE_FR2EN[m.astre] || m.astre) : m.astre;
    const parts = [`- ${name}`];
    if (dom) parts.push(`(${isEN ? 'role' : 'rôle'}: ${dom})`);
    if (m.signe) parts.push(isEN ? `in ${m.signe}` : `en ${m.signe}`);
    if (m.maison) parts.push(isEN ? `— House ${m.maison}: ${L(HOUSE_KW[m.maison])}` : `— Maison ${m.maison} : ${L(HOUSE_KW[m.maison])}`);
    return parts.join(' ');
  }).join('\n');
  const houses = facts.housesCovered.map(h => `${isEN ? 'House' : 'Maison'} ${h.n} (${L(h.domaine)})`).join(isEN ? ' and ' : ' et ');
  const aspects = isEN ? facts.aspectsEn : facts.aspectsFr;
  return [
    `### ${isEN ? 'FIGURE' : 'FIGURE'} ${idx + 1} — id="${idx}" — ${facts.type}`,
    `${isEN ? 'Members' : 'Membres'} :`,
    membersTxt,
    aspects ? `${isEN ? 'Geometric composition' : 'Composition géométrique'} : ${aspects}` : '',
    houses ? `${isEN ? 'Life areas activated' : 'Domaines de vie activés'} : ${houses}` : '',
  ].filter(Boolean).join('\n');
}

